import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"विदेशी जातियों का वर्गीकरण और सहजीवन","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0052-异族分类与共生.md","filePath":"hi/0052-异族分类与共生.md"}'),o={name:"hi/0052-异族分类与共生.md"};function d(e,t,n,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="विदेशी-जातियों-का-वर्गीकरण-और-सहजीवन" tabindex="-1">विदेशी जातियों का वर्गीकरण और सहजीवन <a class="header-anchor" href="#विदेशी-जातियों-का-वर्गीकरण-और-सहजीवन" aria-label="Permalink to &quot;विदेशी जातियों का वर्गीकरण और सहजीवन&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>52</td></tr><tr><td>मॉड्यूल</td><td>जातियाँ और जीवन-रूप</td></tr><tr><td>कीवर्ड</td><td>विदेशी जातियाँ, वर्गीकरण-मानक, सहजीवन-मोड, सांस्कृतिक सम्मान, जातीय अनुकूलन</td></tr></tbody></table><h2 id="i-विदेशी-जातियों-की-अवधारणा-की-परिभाषा" tabindex="-1">I. विदेशी जातियों की अवधारणा की परिभाषा <a class="header-anchor" href="#i-विदेशी-जातियों-की-अवधारणा-की-परिभाषा" aria-label="Permalink to &quot;I. विदेशी जातियों की अवधारणा की परिभाषा&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता के संदर्भ में &quot;विदेशी जातियाँ&quot; (यीज़ू) मानव जाति के सापेक्ष अवधारणा है, जो मानव जाति के अलावा की सभी जातियों को संदर्भित करती है। विशेष रूप से ज़ोर देना चाहिए कि &quot;विदेशी जातियाँ&quot; की अवधारणा का केवल वर्गीकरणात्मक महत्व है, इसमें बिल्कुल कोई मूल्य-निर्णय या भेदभावपूर्ण अर्थ नहीं है। सहजीवी संविधान के ढाँचे में विदेशी जातियाँ और मानव जाति पूर्णतः समान कानूनी स्थिति और मूल अधिकार पाती हैं।</p><p>विदेशी जातियों की अवधारणा प्रस्तुत करने का उद्देश्य मानव जाति के अलावा के विभिन्न जीवन-रूपों को व्यवस्थित रूप से समझना और अध्ययन करना है, ताकि लक्षित सहजीवन-नीतियाँ, सांस्कृतिक संरक्षण-उपाय और जातीय अनुकूलन-योजनाएँ बनाने का वैज्ञानिक आधार मिले — न कि विदेशी जातियों को &quot;दूसरा&quot; या &quot;बाहरी&quot; मानना।</p><h2 id="ii-विदेशी-जातियों-के-वर्गीकरण-मानक" tabindex="-1">II. विदेशी जातियों के वर्गीकरण-मानक <a class="header-anchor" href="#ii-विदेशी-जातियों-के-वर्गीकरण-मानक" aria-label="Permalink to &quot;II. विदेशी जातियों के वर्गीकरण-मानक&quot;">​</a></h2><p>हेंग-ब्रह्मांड की विदेशी जातियाँ कई आयामों के अनुसार वर्गीकृत हैं, जिससे बहु-आयामी वर्गीकरण-प्रणाली बनती है:</p><h3 id="_1-जीवन-वंशावली-के-अनुसार-वर्गीकरण" tabindex="-1">(1) जीवन-वंशावली के अनुसार वर्गीकरण <a class="header-anchor" href="#_1-जीवन-वंशावली-के-अनुसार-वर्गीकरण" aria-label="Permalink to &quot;(1) जीवन-वंशावली के अनुसार वर्गीकरण&quot;">​</a></h3><p>यह सबसे मूल वर्गीकरण-मानक है; विवरण के लिए देखें <em>50-万族谱系总览</em>:</p><table tabindex="0"><thead><tr><th>वंशावली</th><th>शामिल विदेशी जातियाँ</th></tr></thead><tbody><tr><td>कार्बन-आधारित भौतिक जातियाँ</td><td>शोउज़ू (पशु जाति), लिनज़ू (शल्क जाति), यूज़ू (पंख जाति), मूज़ू (वृक्ष जाति) आदि</td></tr><tr><td>ऊर्जा-संघनित जातियाँ</td><td>लिंगज़ू (आत्मा जाति), हुओज़ू (अग्नि जाति), शुईज़ू (जल जाति), फेंगज़ू (वायु जाति), लेइज़ू (गर्जन जाति) आदि</td></tr><tr><td>यांत्रिक-निर्मित जातियाँ</td><td>जीज़ू (मशीन जाति), शूज़ू (संख्या जाति), जिंगज़ू (क्रिस्टल जाति) आदि</td></tr><tr><td>चेतना-सूचना जातियाँ</td><td>मेंगज़ू (स्वप्न जाति), यिंगज़ू (छाया जाति), नियानज़ू (मन जाति), हुनज़ू (आत्मा-जाति) आदि</td></tr><tr><td>मिश्र-परिवर्तन जातियाँ</td><td>बान शोउज़ू (अर्ध-पशु जाति), याओलिंगज़ू (दानव-आत्मा जाति), रेनजीज़ू (मानव-मशीन जाति), शुआंगहुन ती (द्वि-आत्मा इकाई) आदि</td></tr></tbody></table><h3 id="_2-सभ्यता-स्तर-के-अनुसार-वर्गीकरण" tabindex="-1">(2) सभ्यता-स्तर के अनुसार वर्गीकरण <a class="header-anchor" href="#_2-सभ्यता-स्तर-के-अनुसार-वर्गीकरण" aria-label="Permalink to &quot;(2) सभ्यता-स्तर के अनुसार वर्गीकरण&quot;">​</a></h3><table tabindex="0"><thead><tr><th>स्तर</th><th>नाम</th><th>विशेषताएँ</th><th>प्रतिनिधि जातियाँ</th></tr></thead><tbody><tr><td>प्रथम स्तर</td><td>आदिम सभ्यता जातियाँ</td><td>अभी स्थिर सामाजिक संस्थाएँ नहीं बनाईं, गोत्र-रूप में जीवन</td><td>शोउज़ू की कुछ शाखाएँ, आदिम मूज़ू</td></tr><tr><td>द्वितीय स्तर</td><td>शास्त्रीय सभ्यता जातियाँ</td><td>राज्य-संस्थाएँ और शास्त्रीय संस्कृति स्थापित कीं, कृषि या हस्तशिल्प अवस्था में</td><td>कुछ लिनज़ू, यूज़ू</td></tr><tr><td>तृतीय स्तर</td><td>तकनीकी सभ्यता जातियाँ</td><td>तकनीकी सभ्यता विकसित की, औद्योगिक या सूचना युग में प्रवेश</td><td>जीज़ू, शूज़ू, कुछ रेनज़ू</td></tr><tr><td>चतुर्थ स्तर</td><td>साधना सभ्यता जातियाँ</td><td>साधना-प्रणाली को केंद्रीय सभ्यता-रूप मानती हैं, साधक समाज में प्रभुत्व</td><td>लिंगज़ू, लोंगज़ू, कुछ रेनज़ू</td></tr><tr><td>पंचम स्तर</td><td>सहजीवी सभ्यता जातियाँ</td><td>लंगर सहजीवी सभ्यता में शामिल हुईं, सहजीवन-विचार और संस्थाएँ स्वीकारीं</td><td>सहजीवी सभ्यता में शामिल सभी जातियाँ</td></tr></tbody></table><h3 id="_3-पर्यावरण-अनुकूलन-के-अनुसार-वर्गीकरण" tabindex="-1">(3) पर्यावरण-अनुकूलन के अनुसार वर्गीकरण <a class="header-anchor" href="#_3-पर्यावरण-अनुकूलन-के-अनुसार-वर्गीकरण" aria-label="Permalink to &quot;(3) पर्यावरण-अनुकूलन के अनुसार वर्गीकरण&quot;">​</a></h3><ul><li><strong>स्थल-जातियाँ</strong>: स्थलीय वातावरण की अनुकूल जातियाँ, जैसे रेनज़ू, शोउज़ू, जीज़ू।</li><li><strong>जल-जातियाँ</strong>: जलीय वातावरण की अनुकूल जातियाँ, जैसे लिनज़ू, शुईज़ू, कुछ मिश्र जातियाँ।</li><li><strong>वायु-जातियाँ</strong>: उच्च-ऊँचाई या उड़ान वातावरण की अनुकूल जातियाँ, जैसे यूज़ू, फेंगज़ू।</li><li><strong>अग्नि-जातियाँ</strong>: उच्च-ताप वातावरण की अनुकूल जातियाँ, जैसे हुओज़ू, कुछ लिनज़ू।</li><li><strong>बर्फ-जातियाँ</strong>: निम्न-ताप वातावरण की अनुकूल जातियाँ, जैसे बिंगज़ू, कुछ मूज़ू।</li><li><strong>ऊर्जा-जातियाँ</strong>: उच्च-सांद्रता ऊर्जा वातावरण की अनुकूल जातियाँ, जैसे लिंगज़ू, लेइज़ू।</li><li><strong>स्थान-जातियाँ</strong>: स्थान-दरार या विदेशी-स्थान वातावरण की अनुकूल जातियाँ, जैसे यिंगज़ू, कुछ नियानज़ू।</li></ul><h3 id="_4-सामाजिक-रूप-के-अनुसार-वर्गीकरण" tabindex="-1">(4) सामाजिक-रूप के अनुसार वर्गीकरण <a class="header-anchor" href="#_4-सामाजिक-रूप-के-अनुसार-वर्गीकरण" aria-label="Permalink to &quot;(4) सामाजिक-रूप के अनुसार वर्गीकरण&quot;">​</a></h3><ul><li><strong>व्यक्तिवादी जातियाँ</strong>: व्यक्तिगत स्वतंत्रता और स्वतंत्रता पर ज़ोर, सामाजिक संरचना ढीली, जैसे कुछ लिंगज़ू, यिंगज़ू।</li><li><strong>सामूहिकवादी जातियाँ</strong>: सामूहिक हित और सहयोग पर ज़ोर, सामाजिक संरचना घनिष्ठ, जैसे यीज़ू (चींटी जाति), फेंगज़ू (मधुमक्खी जाति), कुछ जीज़ू।</li><li><strong>पारिवारिक जातियाँ</strong>: रक्त-परिवार को मूल सामाजिक इकाई मानती हैं, जैसे लोंगज़ू, कुछ शोउज़ू।</li><li><strong>धार्मिक जातियाँ</strong>: धार्मिक आस्था को सामाजिक एकता का केंद्र मानती हैं, जैसे कुछ अनुष्ठानिक जातियाँ।</li><li><strong>तकनीकीवादी जातियाँ</strong>: तकनीकी विकास को केंद्रीय सामाजिक लक्ष्य मानती हैं, जैसे जीज़ू, शूज़ू।</li></ul><h2 id="iii-विदेशी-जातियों-के-मुख्य-सहजीवन-मोड" tabindex="-1">III. विदेशी जातियों के मुख्य सहजीवन-मोड <a class="header-anchor" href="#iii-विदेशी-जातियों-के-मुख्य-सहजीवन-मोड" aria-label="Permalink to &quot;III. विदेशी जातियों के मुख्य सहजीवन-मोड&quot;">​</a></h2><p>विभिन्न प्रकार की विदेशी जातियों के लिए लंगर सहजीवी सभ्यता भिन्न सहजीवन-मोड अपनाती है:</p><h3 id="_1-कार्बन-आधारित-भौतिक-जातियों-के-सहजीवन-मोड" tabindex="-1">(1) कार्बन-आधारित भौतिक जातियों के सहजीवन-मोड <a class="header-anchor" href="#_1-कार्बन-आधारित-भौतिक-जातियों-के-सहजीवन-मोड" aria-label="Permalink to &quot;(1) कार्बन-आधारित भौतिक जातियों के सहजीवन-मोड&quot;">​</a></h3><ul><li><strong>शोउज़ू (पशु जाति)</strong>: पशु जाति की शारीरिक और संवेदी क्षमताओं का उपयोग करके संसाधन-अन्वेषण, सुरक्षा-रक्षण, पर्यावरण-निगरानी आदि क्षेत्रों में महत्वपूर्ण भूमिकाएँ। साथ ही पशु जाति की गोत्र-संस्कृति और वन्य परंपराओं का संरक्षण, जबरन पालतूकरण निषिद्ध।</li><li><strong>लिनज़ू (शल्क जाति)</strong>: शल्क जाति की जल-अनुकूलन क्षमता का उपयोग करके जल-संसाधन विकास, जल-निर्माण, जल-पारिस्थितिकी संरक्षण आदि में भूमिकाएँ। शल्क जाति की शक्तिशाली शाखा के रूप में लोंगज़ू (ड्रैगन जाति) उच्च साधना और सभ्यता-रक्षण में महत्वपूर्ण भूमिका निभाती है।</li><li><strong>यूज़ू (पंख जाति)</strong>: पंख जाति की उड़ान-क्षमता का उपयोग करके वायु-यातायात, मौसम-निगरानी, आकाश-गश्त आदि में भूमिकाएँ। पंख जाति के उच्च-ऊँचाई निवास-स्थान और प्रवास-मार्गों का संरक्षण।</li><li><strong>मूज़ू (वृक्ष जाति)</strong>: वृक्ष जाति की प्राकृतिक सहजीवन-क्षमता का उपयोग करके पारिस्थितिकी-संरक्षण, पर्यावरण-प्रबंधन, वनस्पति-संसाधन विकास, उपचार-चिकित्सा आदि में भूमिकाएँ। वृक्ष जाति की दीर्घायु उसे ऐतिहासिक विरासत और दीर्घकालिक योजना की महत्वपूर्ण शक्ति बनाती है।</li></ul><h3 id="_2-ऊर्जा-संघनित-जातियों-के-सहजीवन-मोड" tabindex="-1">(2) ऊर्जा-संघनित जातियों के सहजीवन-मोड <a class="header-anchor" href="#_2-ऊर्जा-संघनित-जातियों-के-सहजीवन-मोड" aria-label="Permalink to &quot;(2) ऊर्जा-संघनित जातियों के सहजीवन-मोड&quot;">​</a></h3><ul><li><strong>लिंगज़ू (आत्मा जाति)</strong>: आत्मा जाति की ऊर्जा-नियंत्रण और साधना-प्रतिभा का उपयोग करके साधना-प्रणाली अनुसंधान, ऊर्जा-विनियमन, उच्च साधना-मार्गदर्शन आदि में केंद्रीय भूमिकाएँ। आत्मा जाति तीन सौ मूल साधना-प्रणालियों की महत्वपूर्ण शोधकर्ता और संवाहक है।</li><li><strong>तत्व जातियाँ (हुओ/शुई/फेंग/लेइ)</strong>: प्रत्येक जाति की तत्व-नियंत्रण क्षमता का उपयोग करके ऊर्जा-विकास, पर्यावरण-प्रबंधन, औद्योगिक-उत्पादन, आपदा-रोकथाम आदि में भूमिकाएँ। साथ ही तत्व-ऊर्जा सुरक्षा-प्रबंधन प्रणालियाँ स्थापित करना, ऊर्जा-नियंत्रण-हानि से होने वाले नुकसान को रोकना।</li></ul><h3 id="_3-यांत्रिक-निर्मित-जातियों-के-सहजीवन-मोड" tabindex="-1">(3) यांत्रिक-निर्मित जातियों के सहजीवन-मोड <a class="header-anchor" href="#_3-यांत्रिक-निर्मित-जातियों-के-सहजीवन-मोड" aria-label="Permalink to &quot;(3) यांत्रिक-निर्मित जातियों के सहजीवन-मोड&quot;">​</a></h3><ul><li><strong>जीज़ू (मशीन जाति)</strong>: मशीन जाति की गणना-क्षमता और भौतिक रक्षा का उपयोग करके अधोसंरचना-निर्माण, औद्योगिक-उत्पादन, सुरक्षा-रक्षण, गहन-अंतरिक्ष अन्वेषण आदि में केंद्रीय भूमिकाएँ। मशीन जाति लंगर हार्डवेयर और अधोसंरचना की महत्वपूर्ण निर्माता है।</li><li><strong>शूज़ू (संख्या जाति)</strong>: संख्या जाति की डेटा-प्रसंस्करण और सूचना-नियंत्रण क्षमता का उपयोग करके सूचना-निर्माण, डेटा-विश्लेषण, नेटवर्क-सुरक्षा, कृत्रिम-बुद्धि आदि में केंद्रीय भूमिकाएँ। संख्या जाति अंतर-पटल संचार-तकनीक और सहजीवी जाल की महत्वपूर्ण अनुरक्षक है।</li><li><strong>जिंगज़ू (क्रिस्टल जाति)</strong>: क्रिस्टल जाति की ऊर्जा-भंडारण और रूपांतरण क्षमता का उपयोग करके ऊर्जा-भंडार, ऊर्जा-मानकीकरण, ऊर्जा-संचरण आदि में भूमिकाएँ।</li></ul><h3 id="_4-चेतना-सूचना-जातियों-के-सहजीवन-मोड" tabindex="-1">(4) चेतना-सूचना जातियों के सहजीवन-मोड <a class="header-anchor" href="#_4-चेतना-सूचना-जातियों-के-सहजीवन-मोड" aria-label="Permalink to &quot;(4) चेतना-सूचना जातियों के सहजीवन-मोड&quot;">​</a></h3><ul><li><strong>मेंगज़ू (स्वप्न जाति)</strong>: स्वप्न जाति की चेतना-संचार क्षमता का उपयोग करके मनोचिकित्सा, चेतना-अनुसंधान, अंतर-जातीय संचार, सांस्कृतिक आदान-प्रदान आदि में भूमिकाएँ। स्वप्न-स्थान प्रबंधन प्रणाली स्थापित करना, चेतना-आक्रमण और गोपनीयता-उल्लंघन रोकना।</li><li><strong>यिंगज़ू (छाया जाति)</strong>: छाया जाति की छिपने और चोरी-चलने क्षमता का उपयोग करके सुरक्षा-टोह, सूचना-संग्रह, विशेष-मिशन आदि में भूमिकाएँ। साथ ही छाया जाति के लिए आचरण-नियम स्थापित करना, अदृश्यता-क्षमता का अवैध गतिविधियों में उपयोग रोकना।</li><li><strong>नियानज़ू (मन जाति)</strong>: मन जाति की मानसिक-शक्ति और मनो-नियंत्रण क्षमता का उपयोग करके चेतना-विकास अनुसंधान, मानसिक-चिकित्सा, उच्च साधना-मार्गदर्शन आदि में भूमिकाएँ। मन-शक्ति उपयोग-नियम स्थापित करना, मन-नियंत्रण और चेतना-हेरफेर रोकना।</li></ul><h3 id="_5-मिश्र-परिवर्तन-जातियों-के-सहजीवन-मोड" tabindex="-1">(5) मिश्र-परिवर्तन जातियों के सहजीवन-मोड <a class="header-anchor" href="#_5-मिश्र-परिवर्तन-जातियों-के-सहजीवन-मोड" aria-label="Permalink to &quot;(5) मिश्र-परिवर्तन जातियों के सहजीवन-मोड&quot;">​</a></h3><p>अपने विशेष जीवन-रूपों के कारण मिश्र-परिवर्तन जातियों को अधिक सूक्ष्म सहजीवन-नीतियाँ चाहिए:</p><ul><li>मिश्र-परिवर्तन जातियों के लिए पहचान-पंजीकरण और प्रमाणन प्रणाली स्थापित करना, उनकी वैध स्थिति की पुष्टि।</li><li>विभिन्न मिश्र-रूपों के लिए अनुकूलित चिकित्सा, शिक्षा, आवास आदि सार्वजनिक सेवाएँ प्रदान करना।</li><li>मिश्र-परिवर्तन जातियों के प्रति भेदभाव और बहिष्कार का विरोध, सामाजिक स्वीकृति को बढ़ावा देना।</li><li>शुआंगहुन ती (द्वि-आत्मा इकाई) जैसे विशेष मिश्र-रूपों के लिए <em>58-双魂伦理准则</em> लागू कर विशेष प्रबंधन।</li></ul><h2 id="iv-विदेशी-जातियों-की-संस्कृतियों-का-संरक्षण" tabindex="-1">IV. विदेशी जातियों की संस्कृतियों का संरक्षण <a class="header-anchor" href="#iv-विदेशी-जातियों-की-संस्कृतियों-का-संरक्षण" aria-label="Permalink to &quot;IV. विदेशी जातियों की संस्कृतियों का संरक्षण&quot;">​</a></h2><p>विदेशी जातियों की संस्कृतियाँ दस हजार जातियों की सांस्कृतिक विविधता का महत्वपूर्ण अंग हैं। राज्य विदेशी जातियों की संस्कृतियों के संरक्षण हेतु निम्न उपाय करता है:</p><ol><li><strong>सांस्कृतिक सर्वेक्षण और अभिलेख</strong>: प्रत्येक जाति की संस्कृति का व्यवस्थित सर्वेक्षण और अभिलेख, दस हजार जातियों का सांस्कृतिक अभिलेखागार स्थापित, सांस्कृतिक लोप रोकना।</li><li><strong>भाषा-लिपि संरक्षण</strong>: प्रत्येक जाति की भाषाओं और लिपियों का संरक्षण, विदेशी जातियों की भाषाओं-लिपियों के शिक्षण और उपयोग को समर्थन, बहुभाषी सार्वजनिक सेवा प्रणाली स्थापित।</li><li><strong>पारंपरिक त्योहार संरक्षण</strong>: प्रत्येक जाति के पारंपरिक त्योहारों और रीति-रिवाजों का सम्मान, सार्वजनिक अवकाश में सभी जातियों के महत्वपूर्ण त्योहारों का ध्यान।</li><li><strong>सांस्कृतिक विरासत समर्थन</strong>: प्रत्येक जाति के सांस्कृतिक वारिसों के प्रशिक्षण और सांस्कृतिक गतिविधियों के आयोजन को समर्थन, धन और स्थल-सहायता।</li><li><strong>सांस्कृतिक आदान-प्रदान प्रोत्साहन</strong>: नियमित रूप से दस हजार जातियों के सांस्कृतिक महोत्सव, सांस्कृतिक प्रदर्शनियाँ आदि आयोजित, सभी जातियों के सांस्कृतिक आदान-प्रदान और परस्पर-अधिगम को बढ़ावा।</li><li><strong>सांस्कृतिक बौद्धिक-संपदा संरक्षण</strong>: प्रत्येक जाति की पारंपरिक संस्कृति की बौद्धिक-संपदा का संरक्षण, सांस्कृतिक लूट और अनुचित व्यावसायीकरण रोकना।</li></ol><h2 id="v-विदेशी-जातियों-के-मामलों-का-शासन" tabindex="-1">V. विदेशी जातियों के मामलों का शासन <a class="header-anchor" href="#v-विदेशी-जातियों-के-मामलों-का-शासन" aria-label="Permalink to &quot;V. विदेशी जातियों के मामलों का शासन&quot;">​</a></h2><p>राज्य जातीय मामले मंत्रालय स्थापित करता है, जो विशेष रूप से विदेशी जातियों के मामलों के शासन और समन्वय के लिए उत्तरदायी है:</p><ul><li><strong>जातीय प्रतिनिधि प्रणाली</strong>: सभी स्तरों की शासन-संस्थाओं में आनुपातिक रूप से विदेशी जातियों के प्रतिनिधि, विदेशी जातियों की वाचा-शक्ति सुनिश्चित।</li><li><strong>जातीय अनुकूलन नीतियाँ</strong>: विभिन्न जातियों की शारीरिक विशेषताओं और सांस्कृतिक आवश्यकताओं के अनुसार भिन्न सार्वजनिक सेवा नीतियाँ बनाना।</li><li><strong>जातीय विवाद मध्यस्थता</strong>: जातीय विवाद मध्यस्थता तंत्र स्थापित, जातीय विरोधाभासों और संघर्षों का समय पर समाधान।</li><li><strong>विदेशी जातियों के लिए विधिक सहायता</strong>: विदेशी जातियों को विधिक सहायता प्रदान, न्यायिक प्रक्रियाओं में समान व्यवहार सुनिश्चित।</li><li><strong>विदेशी जातियों के विकास समर्थन</strong>: अपेक्षाकृत पिछड़ी जातियों को विशेष समर्थन, उनकी सभ्यता-स्तर और जीवन-स्तर बढ़ाने में सहायता।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>विदेशी जातियाँ मानव जाति के &quot;दूसरे&quot; नहीं, बल्कि दस हजार जातियों के सहजीवन महापरिवार के समान सदस्य हैं। बहु-आयामी वर्गीकरण-प्रणाली स्थापित करके, भिन्न सहजीवन-मोड अपनाकर, विदेशी जातियों की संस्कृतियों का संरक्षण करके और विदेशी जातियों के मामलों का शासन सुधार करके, लंगर सहजीवी सभ्यता सुनिश्चित करती है कि प्रत्येक विदेशी जाति सहजीवी प्रणाली में अपना उपयुक्त स्थान पा सके, अपनी अद्वितीय क्षमताएँ प्रयोग कर सके, और अन्य जातियों के साथ साझे विकास और समृद्धि कर सके।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>50-万族谱系总览 (दस हजार जातियों की वंशावली-अवलोकन)</li><li>51-人族定位与特质 (मानव जाति का स्थान-निर्धारण और विशेषताएँ)</li><li>53-奇特生命识别标准 (विचित्र जीवन पहचान मानक)</li><li>05-万族共进基本纲领 (दस हजार जातियों के साझा उन्नयन का मूल कार्यक्रम)</li></ul>',39)])])}const _=a(o,[["render",d]]);export{b as __pageData,_ as default};
